        // Set how much the body, head, and eyes will be influenced by the IK.
        _animator.SetLookAtWeight(1f, _aimBodyWeight, _aimHeadWeight, 1f, 0.5f);

        // --- THE DEFINITIVE FIX ---

        // 1. Find the head bone. If it doesn't exist, do nothing.
