using UnityEngine;

public class PlayerMovement
{
    // --- Settings ---
    private readonly float _moveSpeed;
    private readonly float _accelerationTime;

    // --- Dash Settings ---
    private readonly float _dashSpeed = 30f;
    private readonly float _dashDuration = 0.1f;
    private readonly float _dashCooldown = 1f;

    // --- References ---
    private readonly CharacterController _controller;
    private readonly Transform _cameraTransform;

    // --- State ---
    private Vector3 _currentMoveVelocity;
    private Vector3 _velocityDamper;
    private float _dashCooldownTimer;
    private float _dashTimer;
    private bool _isDashing;

    // --- Public State ---
    public bool JustDashed { get; private set; }
    public float DashCooldownTimer => _dashCooldownTimer;

    public PlayerMovement(CharacterController controller, Transform cameraTransform, float moveSpeed, float accelerationTime)
    {
        _controller = controller;
        _cameraTransform = cameraTransform;
        _moveSpeed = moveSpeed;
        _accelerationTime = accelerationTime;
    }

    public void Tick()
    {
        JustDashed = false; 
        float horizontalInput = Input.GetAxisRaw("Horizontal");
        float verticalInput = Input.GetAxisRaw("Vertical");

        // --- Camera-Relative Direction Calculation ---
        // Get camera's forward and right vectors, then flatten them on the XZ plane.
        Vector3 camForward = _cameraTransform.forward;
        camForward.y = 0;
        camForward.Normalize();

        Vector3 camRight = _cameraTransform.right;
        camRight.y = 0;
        camRight.Normalize();

        // Combine inputs with camera vectors to get the final world-space direction.
        Vector3 moveDirection = (camForward * verticalInput + camRight * horizontalInput).normalized;

        // --- State Handling ---
        HandleDashState(moveDirection);

        if (_isDashing)
        {
            // During a dash, we use the calculated move direction at full dash speed.
            _controller.Move(moveDirection * _dashSpeed * Time.deltaTime);
            return;
        }

        // --- Standard Movement ---
        // Apply regular movement speed to the calculated direction.
        Vector3 targetVelocity = moveDirection * _moveSpeed;
        _currentMoveVelocity = Vector3.SmoothDamp(_currentMoveVelocity, targetVelocity, ref _velocityDamper, _accelerationTime);
        _controller.Move(_currentMoveVelocity * Time.deltaTime);
    }

    private void HandleDashState(Vector3 moveDirection)
    {
        if (_dashCooldownTimer > 0) _dashCooldownTimer -= Time.deltaTime;

        if (_dashTimer > 0)
        {
            _dashTimer -= Time.deltaTime;
            if (_dashTimer <= 0) _isDashing = false;
        }

        if (Input.GetKeyDown(KeyCode.Space) && _dashCooldownTimer <= 0 && moveDirection.sqrMagnitude > 0.1f)
        {
            JustDashed = true; 
            _isDashing = true;
            _dashCooldownTimer = _dashCooldown;
            _dashTimer = _dashDuration;
        }
    }
}

using UnityEngine;
using UnityEngine.AI; // Ważne, aby dodać tę linię!

[RequireComponent(typeof(NavMeshAgent))]
public class EnemyAI : MonoBehaviour
{
    // --- Konfiguracja w Inspektorze ---
    [Header("Dependencies")]
    [Tooltip("Obiekt gracza, który ma być śledzony.")]
    [SerializeField] private Transform _playerTransform;

    [Header("AI Settings")]
    [Tooltip("Jak daleko wróg 'widzi' gracza.")]
    [SerializeField] private float _detectionRadius = 15f;
    [Tooltip("Jak blisko wróg musi podejść, aby zacząć strzelać.")]
    [SerializeField] private float _attackRange = 10f;

    [Header("Weapon Settings")]
    [SerializeField] private float _fireRate = 1f; // Strzałów na sekundę
    [SerializeField] private GameObject _bulletPrefab;
    [SerializeField] private Transform _firePoint;
    [SerializeField] private float _bulletSpeed = 20f;


    // --- Stany AI ---
    private enum State
    {
        Idle,
        Chasing,
        Attacking
    }
    private State _currentState;

    // --- Komponenty ---
    private NavMeshAgent _navAgent;

    // --- Zmienne wewnętrzne ---
    private float _distanceToPlayer;
    private float _nextFireTime;

    void Awake()
    {
        _navAgent = GetComponent<NavMeshAgent>();
        // Na początku próbujemy znaleźć gracza automatycznie po tagu "Player"
        if (_playerTransform == null)
        {
            GameObject player = GameObject.FindGameObjectWithTag("Player");
            if(player != null)
            {
                _playerTransform = player.transform;
            }
        }
    }

    void Start()
    {
        // Rozpoczynamy w stanie spoczynku
        _currentState = State.Idle;
    }

    void Update()
    {
        if (_playerTransform == null)
        {
            // Jeśli nie ma gracza, nic nie rób
            _navAgent.isStopped = true;
            return;
        }

        _distanceToPlayer = Vector3.Distance(transform.position, _playerTransform.position);

        // --- Automat Stanów (State Machine) ---
        switch (_currentState)
        {
            case State.Idle:
                HandleIdleState();
                break;
            case State.Chasing:
                HandleChasingState();
                break;
            case State.Attacking:
                HandleAttackingState();
                break;
        }
    }

    // --- Logika dla każdego stanu ---

    private void HandleIdleState()
    {
        // W stanie spoczynku sprawdzamy, czy gracz wszedł w zasięg detekcji
        if (_distanceToPlayer <= _detectionRadius)
        {
            _currentState = State.Chasing;
        }
    }

    private void HandleChasingState()
    {
        // W stanie pościgu, AI podąża za graczem
        _navAgent.isStopped = false;
        _navAgent.SetDestination(_playerTransform.position);

        // Jeśli gracz wejdzie w zasięg ataku, przejdź do stanu ataku
        if (_distanceToPlayer <= _attackRange)
        {
            _currentState = State.Attacking;
        }
        // Jeśli gracz ucieknie poza zasięg detekcji, wróć do stanu spoczynku
        else if (_distanceToPlayer > _detectionRadius)
        {
            _currentState = State.Idle;
            _navAgent.isStopped = true;
        }
    }

    private void HandleAttackingState()
    {
        // W stanie ataku, AI zatrzymuje się
        _navAgent.isStopped = true;

        // Obraca się w stronę gracza
        Vector3 lookDirection = (_playerTransform.position - transform.position).normalized;
        lookDirection.y = 0; // Upewnij się, że obraca się tylko horyzontalnie
        transform.rotation = Quaternion.LookRotation(lookDirection);

        // I strzela z określoną częstotliwością
        if (Time.time >= _nextFireTime)
        {
            Fire();
            _nextFireTime = Time.time + 1f / _fireRate;
        }

        // Jeśli gracz ucieknie z zasięgu ataku, wróć do pościgu
        if (_distanceToPlayer > _attackRange)
        {
            _currentState = State.Chasing;
        }
    }

    private void Fire()
    {
        if (_bulletPrefab == null || _firePoint == null) return;

        GameObject bulletGO = Instantiate(_bulletPrefab, _firePoint.position, _firePoint.rotation);
        Bullet bullet = bulletGO.GetComponent<Bullet>();

        if (bullet != null)
        {
            // Używamy tego samego komponentu pocisku, co gracz
            Vector3 shootDirection = (_playerTransform.position - _firePoint.position).normalized;
            bullet.Fire(shootDirection, _bulletSpeed);
        }
        else
        {
            // Prosty fallback, jeśli pocisk nie ma skryptu 'Bullet'
            Rigidbody rb = bulletGO.GetComponent<Rigidbody>();
            if(rb != null)
            {
                rb.velocity = (_playerTransform.position - _firePoint.position).normalized * _bulletSpeed;
            }
        }
    }

    // --- Wizualizacja w edytorze ---
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.yellow;
        Gizmos.DrawWireSphere(transform.position, _detectionRadius);
        Gizmos.color = Color.red;
        Gizmos.DrawWireSphere(transform.position, _attackRange);
    }
}

using UnityEngine;
using UnityEngine.AI; // Ważne, aby dodać tę linię!

[RequireComponent(typeof(NavMeshAgent))]
public class EnemyAI : MonoBehaviour
{
    // --- NOWA OPCJA: Typ ataku ---
    public enum AttackType { Ranged, Melee }

    [Header("AI Behavior")]
    [Tooltip("Wybierz, czy wróg atakuje z dystansu czy w zwarciu.")]
    [SerializeField] private AttackType _attackType = AttackType.Ranged;

    // --- Konfiguracja w Inspektorze ---
    [Header("Dependencies")]
    [Tooltip("Obiekt gracza, który ma być śledzony.")]
    [SerializeField] private Transform _playerTransform;

    [Header("AI Stats")]
    [Tooltip("Jak daleko wróg 'widzi' gracza.")]
    [SerializeField] private float _detectionRadius = 15f;
    [Tooltip("Jak blisko wróg musi podejść, aby zaatakować. Dla Melee ustaw małą wartość (np. 1.5), dla Ranged dużą (np. 10).")]
    [SerializeField] private float _attackRange = 10f;
    [Tooltip("Częstotliwość ataków (ataków na sekundę).")]
    [SerializeField] private float _attackRate = 1f;

    [Header("Ranged Weapon Settings (jeśli AttackType = Ranged)")]
    [SerializeField] private GameObject _bulletPrefab;
    [SerializeField] private Transform _firePoint;
    [SerializeField] private float _bulletSpeed = 20f;

    [Header("Melee Settings (jeśli AttackType = Melee)")]
    [SerializeField] private int _meleeDamage = 10;


    // --- Stany AI ---
    private enum State
    {
        Idle,
        Chasing,
        Attacking
    }
    private State _currentState;

    // --- Komponenty ---
    private NavMeshAgent _navAgent;

    // --- Zmienne wewnętrzne ---
    private float _distanceToPlayer;
    private float _nextAttackTime;

    void Awake()
    {
        _navAgent = GetComponent<NavMeshAgent>();
        if (_playerTransform == null)
        {
            GameObject player = GameObject.FindGameObjectWithTag("Player");
            if(player != null)
            {
                _playerTransform = player.transform;
            }
        }
    }

    void Start()
    {
        _currentState = State.Idle;
    }

    void Update()
    {
        if (_playerTransform == null)
        {
            _navAgent.isStopped = true;
            return;
        }

        _distanceToPlayer = Vector3.Distance(transform.position, _playerTransform.position);

        switch (_currentState)
        {
            case State.Idle:
                HandleIdleState();
                break;
            case State.Chasing:
                HandleChasingState();
                break;
            case State.Attacking:
                HandleAttackingState();
                break;
        }
    }

    // --- Logika dla każdego stanu ---

    private void HandleIdleState()
    {
        if (_distanceToPlayer <= _detectionRadius)
        {
            _currentState = State.Chasing;
        }
    }

    private void HandleChasingState()
    {
        _navAgent.isStopped = false;
        _navAgent.SetDestination(_playerTransform.position);

        if (_distanceToPlayer <= _attackRange)
        {
            _currentState = State.Attacking;
        }
        else if (_distanceToPlayer > _detectionRadius)
        {
            _currentState = State.Idle;
            _navAgent.isStopped = true;
        }
    }

    private void HandleAttackingState()
    {
        _navAgent.isStopped = true;

        Vector3 lookDirection = (_playerTransform.position - transform.position).normalized;
        lookDirection.y = 0;
        transform.rotation = Quaternion.LookRotation(lookDirection);

        if (Time.time >= _nextAttackTime)
        {
            // --- NOWA LOGIKA: Wykonaj odpowiedni atak ---
            if (_attackType == AttackType.Ranged)
            {
                PerformRangedAttack();
            }
            else // Melee
            {
                PerformMeleeAttack();
            }
            _nextAttackTime = Time.time + 1f / _attackRate;
        }

        if (_distanceToPlayer > _attackRange)
        {
            _currentState = State.Chasing;
        }
    }

    private void PerformRangedAttack()
    {
        if (_bulletPrefab == null || _firePoint == null) return;

        GameObject bulletGO = Instantiate(_bulletPrefab, _firePoint.position, _firePoint.rotation);
        Bullet bullet = bulletGO.GetComponent<Bullet>();

        if (bullet != null)
        {
            Vector3 shootDirection = (_playerTransform.position - _firePoint.position).normalized;
            bullet.Fire(shootDirection, _bulletSpeed);
        }
        else
        {
            Rigidbody rb = bulletGO.GetComponent<Rigidbody>();
            if(rb != null)
            {
                rb.velocity = (_playerTransform.position - _firePoint.position).normalized * _bulletSpeed;
            }
        }
    }

    private void PerformMeleeAttack()
    {
        // Sprawdzamy, czy gracz jest wciąż w zasięgu w momencie ataku
        if (_distanceToPlayer <= _attackRange)
        {
            Debug.Log($"Wróg wykonał atak MELEE na graczu {_playerTransform.name}, zadając {_meleeDamage} obrażeń!");
            // W tym miejscu w przyszłości wywołasz funkcję zadającą obrażenia graczowi, np.:
            // _playerTransform.GetComponent<PlayerHealth>().TakeDamage(_meleeDamage);
        }
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.yellow;
        Gizmos.DrawWireSphere(transform.position, _detectionRadius);
        Gizmos.color = Color.red;
        Gizmos.DrawWireSphere(transform.position, _attackRange);
    }
}

using UnityEngine;
using UnityEngine.AI;

[RequireComponent(typeof(NavMeshAgent))]
public class EnemyAI : MonoBehaviour
{
    // --- NOWY TYP: Exploder ---
    public enum AttackType { Ranged, Melee, Exploder }

    [Header("AI Behavior")]
    [Tooltip("Wybierz, czy wróg atakuje z dystansu, w zwarciu, czy wybucha.")]
    [SerializeField] private AttackType _attackType = AttackType.Ranged;

    [Header("Dependencies")]
    [Tooltip("Obiekt gracza, który ma być śledzony.")]
    [SerializeField] private Transform _playerTransform;

    [Header("AI Stats")]
    [Tooltip("Jak daleko wróg 'widzi' gracza.")]
    [SerializeField] private float _detectionRadius = 15f;
    [Tooltip("Jak blisko wróg musi podejść, aby zaatakować/wybuchnąć.")]
    [SerializeField] private float _attackRange = 10f;
    [Tooltip("Częstotliwość ataków (dla Ranged i Melee).")]
    [SerializeField] private float _attackRate = 1f;

    [Header("Ranged Weapon Settings (jeśli Ranged)")]
    [SerializeField] private GameObject _bulletPrefab;
    [SerializeField] private Transform _firePoint;
    [SerializeField] private float _bulletSpeed = 20f;

    [Header("Melee Settings (jeśli Melee)")]
    [SerializeField] private int _meleeDamage = 10;

    [Header("Exploder Settings (jeśli Exploder)")]
    [SerializeField] private int _explosionDamage = 50;
    [SerializeField] private float _explosionRadius = 5f;
    [Tooltip("Czas w sekundach od zatrzymania się do wybuchu.")]
    [SerializeField] private float _explosionFuseTime = 1.5f;

    private enum State { Idle, Chasing, Attacking }
    private State _currentState;
    private NavMeshAgent _navAgent;

    private float _distanceToPlayer;
    private float _nextAttackTime;
    private float _fuseTimer; // Odliczanie do eksplozji

    void Awake()
    {
        _navAgent = GetComponent<NavMeshAgent>();
        if (_playerTransform == null)
        {
            GameObject player = GameObject.FindGameObjectWithTag("Player");
            if(player != null) _playerTransform = player.transform;
        }
    }

    void Start()
    {
        _currentState = State.Idle;
    }

    void Update()
    {
        if (_playerTransform == null)
        {
            _navAgent.isStopped = true;
            return;
        }

        _distanceToPlayer = Vector3.Distance(transform.position, _playerTransform.position);

        switch (_currentState)
        {
            case State.Idle: HandleIdleState(); break;
            case State.Chasing: HandleChasingState(); break;
            case State.Attacking: HandleAttackingState(); break;
        }
    }

    private void HandleIdleState()
    {
        if (_distanceToPlayer <= _detectionRadius)
        {
            _currentState = State.Chasing;
        }
    }

    private void HandleChasingState()
    {
        _navAgent.isStopped = false;
        _navAgent.SetDestination(_playerTransform.position);

        if (_distanceToPlayer <= _attackRange)
        {
            _currentState = State.Attacking;
            // Jeśli to exploder, włączamy jego "zapalnik"
            if (_attackType == AttackType.Exploder)
            {
                _fuseTimer = _explosionFuseTime;
            }
        }
        else if (_distanceToPlayer > _detectionRadius)
        {
            _currentState = State.Idle;
            _navAgent.isStopped = true;
