using UnityEngine;

[RequireComponent(typeof(Rigidbody))]
public class Bullet : MonoBehaviour
{
    private Rigidbody _rb;
    private ObjectPool<Bullet> _pool;
    private float _lifetime = 3f;
    private float _timer;

    // --- FIX 1: Get Rigidbody in Awake ---
    // Awake is called automatically when an object is instantiated,
    // ensuring _rb is never null, regardless of who creates the bullet.
    void Awake()
    {
        _rb = GetComponent<Rigidbody>();
    }

    public void Init(ObjectPool<Bullet> pool)
    {
        _pool = pool;
    }

    public void Fire(Vector3 dir, float speed)
    {
        _timer = _lifetime;
        if (_rb != null)
        {
            _rb.velocity = dir * speed;
        }
    }

    void Update()
    {
        _timer -= Time.deltaTime;
        if (_timer <= 0)
        {
            Deactivate();
        }
    }

    private void OnTriggerEnter(Collider other)
    {
        if (other.CompareTag("Enemy"))
        {
            Debug.Log("Hit enemy: " + other.name);
        }

        Deactivate();
    }

    // --- FIX 2: Handle deactivation smartly ---
    // This method decides whether to return the bullet to a pool or destroy it.
    private void Deactivate()
    {
        if (_pool != null)
        {
            // If the bullet belongs to a pool, return it.
            _pool.ReturnObject(this);
        }
        else
        {
            // If it was instantiated manually (by the enemy), just destroy it.
            Destroy(gameObject);
        }
    }
}

