using UnityEngine;
using UnityEngine.Events; // Potrzebne do UnityEvent

public class Health : MonoBehaviour
{
    [Header("Health Settings")]
    [SerializeField] private float maxHealth = 100f;

    [Header("Events")]
    [Tooltip("Wywoływane, gdy obiekt umiera. Możesz tu podpiąć np. efekty eksplozji, menedżer gry etc.")]
    public UnityEvent OnDie;

    private float _currentHealth;

    // --- Publiczne właściwości ---
    public float CurrentHealth => _currentHealth;
    public float MaxHealth => maxHealth;

    private void Awake()
    {
        // Na starcie każdy ma pełne zdrowie
        _currentHealth = maxHealth;
    }

    /// <summary>
    /// Zmniejsza punkty zdrowia obiektu o podaną wartość.
    /// </summary>
    /// <param name="amount">Ilość obrażeń do otrzymania.</param>
    public void TakeDamage(float amount)
    {
        if (_currentHealth <= 0) return; // Już jest martwy, nic nie rób

        _currentHealth -= amount;
        Debug.Log($"{gameObject.name} otrzymał {amount} obrażeń. Pozostało zdrowia: {_currentHealth}");

        if (_currentHealth <= 0)
        {
            Die();
        }
    }

    private void Die()
    {
        Debug.Log($"{gameObject.name} umarł.");

        // Wywołaj wszystkie funkcje podpięte do zdarzenia OnDie w Inspektorze
        OnDie?.Invoke();

        // Zniszcz obiekt
        Destroy(gameObject);
    }
}

